class Solution {
public:
    vector<vector<int>> construct2DArray(vector<int>& original, int m, int n) {
        int sz = (int)original.size();
        if ((long long)m * n != sz) {
            return {};
        }
        vector<vector<int>> res(m, vector<int>(n));
        for (int i = 0; i < sz; i++) {
            res[i / n][i % n] = original[i];
        }
        return res;
    }
};
